    private static readonly Dictionary<string, string[]> HelpSections = new(StringComparer.Ordinal)
    {
        ["Демонстрация Что я умею"] = [
            "В меню «Что я умею» запускается интерактивный граф после согласия. Он спрашивает имя и фразу, печатает персональное приветствие в Блокноте, определяет исходный язык приближённо и переводит на выбранный из шести языков встроенной офлайн-моделью. Затем Paint рисует звезду, сердце или дом движением мыши; ответ «Нет» позволяет выбрать другую фигуру, пока вы не выберете продолжение. После этого четыре картинки 100×100 открываются в отдельных окнах Paint. Переместите окна и нажмите ОК: Kliker Blocks ищет большой участок выбранного цвета, закрывает только три демонстрационных окна и ставит найденное по центру. Последняя глава графа показывает переменные, массивы, условия, циклы, INI, файлы, буфер и журнал. Сохранённые файлы и оставшиеся окна не удаляются; путь к отчёту виден в журнале. Esc или «Остановить» прерывает действия. Не запускайте демонстрацию поверх конфиденциальных данных.",
            "What I can do runs an interactive graph after consent. It asks for your name and text, types a personal greeting in Notepad, estimates the source language and translates into one of six languages using bundled offline models. Paint visibly draws a star, heart or house with mouse strokes. No lets you choose another shape, until you choose to continue. Four 100×100 images then open in separate Paint windows. Move them and press OK: Kliker Blocks searches for a large patch of the chosen color, closes only the other three demo windows and centers the match. A final graph chapter demonstrates variables, arrays, branches, loops, INI, files, clipboard and journal. Saved files and remaining windows are kept; the report path is logged. Esc or Stop interrupts later actions. Do not run over sensitive content.",
            "Ce que je sais faire lance un graphe interactif après accord. Il demande votre nom et un texte, écrit un message personnel dans le Bloc-notes, estime la langue source et traduit vers une des six langues avec les modèles hors ligne inclus. Paint dessine une étoile, un cœur ou une maison avec la souris. Non permet un autre dessin, jusqu'à ce que vous choisissiez de continuer. Quatre images 100×100 s'ouvrent dans des fenêtres Paint distinctes. Déplacez-les et cliquez sur OK : Kliker Blocks cherche la couleur choisie, ferme uniquement les trois autres fenêtres de la démo et centre la bonne. La suite montre variables, tableaux, conditions, boucles, INI, fichiers, presse-papiers et journal. Les fichiers restent ; leur chemin est dans le journal. Échap ou Arrêter interrompt la démo. Évitez les données sensibles.",
            "Lo que puedo hacer inicia un grafo interactivo con su permiso. Pide nombre y texto, escribe un saludo en Bloc de notas, estima el idioma de origen y traduce a uno de seis idiomas con modelos sin conexión incluidos. Paint dibuja una estrella, un corazón o una casa con el ratón. No permite elegir otra figura, hasta que elija continuar. Cuatro imágenes de 100×100 se abren en ventanas de Paint separadas. Muévalas y pulse Aceptar: Kliker Blocks busca el color elegido, cierra solo las otras tres ventanas de la demo y centra la correcta. La última parte muestra variables, matrices, condiciones, bucles, INI, archivos, portapapeles y registro. Los archivos permanecen y su ruta aparece en el registro. Esc o Detener interrumpe la demo. Evite datos sensibles.",
            "“我能做什么”会在您同意后运行交互图表。它询问姓名和文字，在记事本中输入个性化问候，估计源语言，并用内置离线模型翻译成六种语言之一。Paint 会用鼠标画星星、爱心或房子；选择“否”可重画，直到您选择继续。随后四张 100×100 图片在独立 Paint 窗口中打开。移动窗口并点击确定：Kliker Blocks 搜索所选颜色的大面积区域，只关闭另外三个演示窗口，并将匹配窗口居中。最后一章展示变量、数组、条件、循环、INI、文件、剪贴板和日志。保存的文件会保留，路径显示在日志中。Esc 或“停止”可中断；请勿在敏感内容上运行。",
            "„Was ich kann“ startet nach Zustimmung einen interaktiven Graphen. Er fragt nach Name und Text, tippt eine persönliche Begrüßung in Notepad, schätzt die Ausgangssprache und übersetzt mit integrierten Offline-Modellen in eine von sechs Sprachen. Paint zeichnet Stern, Herz oder Haus sichtbar mit der Maus; Nein erlaubt bis Sie fortfahren möchten. Vier 100×100-Bilder werden danach in eigenen Paint-Fenstern geöffnet. Verschieben Sie sie und klicken Sie OK: Kliker Blocks sucht die gewählte Farbe, schließt nur die drei anderen Demo-Fenster und zentriert das passende. Der letzte Teil zeigt Variablen, Arrays, Bedingungen, Schleifen, INI, Dateien, Zwischenablage und Protokoll. Dateien bleiben erhalten, der Berichtspfad steht im Protokoll. Esc oder Stopp unterbricht die Demo. Nicht über vertraulichen Daten starten."
        ],
        ["Окна и точность демонстрации"] = [
            "Когда хватает места, Блокнот слева, граф и вопросы справа. Ввод ускорен и проверяется копированием всего документа; при пропуске символов текст исправляется через буфер. Paint открывается с пустым холстом, Kliker Blocks находит карандаш и красный цвет, определяет белую область, рисует мышью и проверяет появление штрихов. Цветные картинки имеют размер 100×100; поиск требует большого участка цвета, а не одиночного пикселя палитры. Чужие окна Paint не закрываются. Если установленный Paint открывает файлы только вкладками или не даёт четыре независимых окна, демонстрация сообщает об ошибке и не закрывает пользовательские окна. На узком экране окна могут перекрыться.",
            "When space permits, Notepad is left of the graph and prompts are on the right. Faster typing is checked by copying the entire document; missed characters are corrected through the clipboard. Paint starts blank; Kliker Blocks finds its pencil and red color, locates the white canvas, draws with the mouse and checks the strokes. Color images are 100×100; search requires a large color patch, not one palette pixel. Other Paint windows are never closed. If Paint opens files only as tabs or cannot provide four separate windows, the demo reports an error and leaves user windows untouched. Narrow screens may overlap.",
            "Si l'espace le permet, le Bloc-notes est à gauche et les questions à droite. La saisie rapide est vérifiée en copiant tout le document ; les caractères manquants sont corrigés par le presse-papiers. Paint démarre vide : Kliker Blocks trouve le crayon, le rouge et le canevas blanc, dessine à la souris et vérifie les traits. La recherche des images 100×100 exige une grande zone colorée, pas un pixel de la palette. Les autres fenêtres Paint ne sont jamais fermées. Si Paint n'ouvre que des onglets ou refuse quatre fenêtres distinctes, une erreur est signalée. Les petits écrans peuvent chevaucher les fenêtres.",
            "Si hay espacio, Bloc de notas queda a la izquierda y las preguntas a la derecha. La escritura rápida se verifica copiando todo el documento; se corrigen caracteres perdidos mediante el portapapeles. Paint empieza en blanco: Kliker Blocks busca lápiz, rojo y lienzo, dibuja con el ratón y verifica los trazos. La búsqueda de imágenes 100×100 exige un área grande del color, no un píxel de la paleta. Nunca se cierran otras ventanas Paint. Si Paint solo usa pestañas o no permite cuatro ventanas distintas, se informa del error. En pantallas pequeñas puede haber solapamiento.",
            "空间允许时，记事本放在左边，问题放在右边。加速输入后会复制整篇文档进行核对；漏字通过剪贴板修正。Paint 从空白画布开始：Kliker Blocks 定位铅笔、红色和白色画布，用鼠标绘制并检查笔迹。100×100 彩图的搜索需要一大片颜色，不会把调色板中的单个像素当成结果。不会关闭其他 Paint 窗口。如果 Paint 只打开选项卡或无法创建四个独立窗口，演示会报错。窄屏幕可能出现窗口重叠。",
            "Wenn Platz ist, steht Notepad links und die Fragen rechts. Schnellere Eingaben werden durch Kopieren des ganzen Dokuments geprüft; fehlende Zeichen werden über die Zwischenablage korrigiert. Paint startet leer: Kliker Blocks findet Stift, Rot und weiße Leinwand, zeichnet mit der Maus und prüft die Striche. Die Suche nach 100×100-Farbbildern verlangt eine große Farbfläche statt eines Palettenpixels. Fremde Paint-Fenster werden nicht geschlossen. Öffnet Paint nur Tabs oder keine vier getrennten Fenster, meldet die Demo einen Fehler. Auf kleinen Bildschirmen können Fenster überlappen."
        ],
        ["Перевод текста и языковые модели"] = [
            "Публикуемая версия содержит собственный Python, Argos Translate и модели для русского, английского, французского, испанского, китайского и немецкого. Эти языки переводятся друг в друга через встроенные направления, иногда через английский. Интернет и ручная установка не нужны. Блок «Перевести текст» с движком «Argos локально» требует конкретный язык источника и цели; качество различается. LibreTranslate остаётся отдельным необязательным сервером для HTTP-перевода и блоков определения языка/проверки пары. В демонстрации исходный язык определяется приближённо по письму и распространённым словам; короткие фразы могут быть распознаны неверно.",
            "The published app bundles Python, Argos Translate and models for Russian, English, French, Spanish, Chinese and German. They translate into one another using built-in routes, sometimes via English. No internet or manual setup is needed. Local Argos Translate text needs explicit source and target codes; quality varies. LibreTranslate is a separate optional server for HTTP translation, Detect language and pair checks. The demo only estimates a source language from script and common words; short phrases can be misidentified.",
            "L'application publiée inclut Python, Argos Translate et les modèles pour russe, anglais, français, espagnol, chinois et allemand. Toutes ces langues se traduisent entre elles, parfois via l'anglais, sans Internet ni installation manuelle. Le bloc Argos local exige les codes source et cible ; la qualité varie. LibreTranslate reste un serveur facultatif pour la traduction HTTP, la détection et la vérification des paires. La démo estime seulement la langue source : une phrase courte peut être mal reconnue.",
            "La aplicación publicada incluye Python, Argos Translate y modelos para ruso, inglés, francés, español, chino y alemán. Estas lenguas se traducen entre sí, a veces mediante inglés, sin Internet ni instalación manual. El bloque Argos local exige origen y destino explícitos; la calidad varía. LibreTranslate sigue siendo un servidor opcional para traducción HTTP, detección y consulta de pares. La demo solo estima el idioma de origen; una frase breve puede identificarse mal.",
            "发布版内置 Python、Argos Translate，以及俄语、英语、法语、西班牙语、中文和德语模型。六种语言可互译，有些方向经英语中转，无需联网或手动安装。使用“本地 Argos”翻译块时需明确源语言和目标语言；质量因语言对而异。LibreTranslate 仍是可选的独立服务器，用于 HTTP 翻译、语言检测和语言对查询。演示仅估计源语言，短句可能判断错误。",
            "Die veröffentlichte App enthält Python, Argos Translate und Modelle für Russisch, Englisch, Französisch, Spanisch, Chinesisch und Deutsch. Diese Sprachen lassen sich untereinander übersetzen, teils über Englisch, ohne Internet oder manuelle Installation. Der lokale Argos-Block braucht Quell- und Zielcodes; die Qualität variiert. LibreTranslate bleibt ein optionaler separater Server für HTTP-Übersetzung, Spracherkennung und Paarabfrage. Die Demo schätzt die Ausgangssprache nur; kurze Sätze können falsch erkannt werden."
        ],
        ["Установка модели Argos"] = [
            "Для шести встроенных языков ничего устанавливать не нужно: встроенный Python и модели уже входят в папку публикации. В поле Python оставьте «Встроенный» или «python»; проверка Argos покажет доступные пары. Для другого языка скачайте доверенный .argosmodel нужного направления, нажмите «Установить .argosmodel…» и проверьте список. Дополнительные модели хранятся отдельно в %LOCALAPPDATA%\\KLIKER Blocks\\LanguageModels\\Packages. Пользовательский Python можно указать только при необходимости. Ошибка соединения с 127.0.0.1:5000 относится к необязательному серверу LibreTranslate и не мешает локальному переводу.",
            "Nothing must be installed for the six bundled languages: Python and models ship with the published app. Leave Python as Built-in or python; Check Argos lists available pairs. For another language, download a trusted .argosmodel in the required direction, choose Install .argosmodel and inspect the list. Extra models live separately under %LOCALAPPDATA%\\KLIKER Blocks\\LanguageModels\\Packages. Specify a custom Python only if needed. A connection error at 127.0.0.1:5000 refers to optional LibreTranslate and does not affect offline translation.",
            "Pour les six langues incluses, aucune installation n'est nécessaire : Python et les modèles sont fournis. Laissez Python sur Intégré ou python ; Vérifier Argos affiche les paires. Pour une autre langue, téléchargez un .argosmodel fiable dans le bon sens, choisissez Installer .argosmodel et vérifiez la liste. Les modèles supplémentaires vont dans %LOCALAPPDATA%\\KLIKER Blocks\\LanguageModels\\Packages. Un Python personnalisé n'est utile qu'au besoin. L'erreur de connexion à 127.0.0.1:5000 concerne LibreTranslate, pas la traduction locale.",
            "Para los seis idiomas incluidos no hay que instalar nada: Python y los modelos vienen en la aplicación. Deje Python como Integrado o python; Comprobar Argos muestra los pares. Para otro idioma, descargue un .argosmodel fiable en la dirección correcta, elija Instalar .argosmodel y compruebe la lista. Los modelos extra se guardan en %LOCALAPPDATA%\\KLIKER Blocks\\LanguageModels\\Packages. Solo indique otro Python si es necesario. El error 127.0.0.1:5000 pertenece al servidor LibreTranslate opcional y no afecta la traducción local.",
            "六种内置语言无需安装：发布版已附带 Python 和模型。Python 保持“内置”或 python；“检查 Argos”会列出可用语言对。其他语言可下载可信且方向正确的 .argosmodel，点击“安装 .argosmodel”，然后核对列表。附加模型保存在 %LOCALAPPDATA%\\KLIKER Blocks\\LanguageModels\\Packages。只有必要时才指定自定义 Python。127.0.0.1:5000 的连接错误属于可选 LibreTranslate 服务，不影响离线翻译。",
            "Für die sechs enthaltenen Sprachen ist keine Installation nötig: Python und Modelle werden mitgeliefert. Lassen Sie Python auf Integriert oder python; Argos prüfen zeigt die Paare. Für weitere Sprachen laden Sie ein vertrauenswürdiges .argosmodel der passenden Richtung, wählen .argosmodel installieren und prüfen die Liste. Zusatzmodelle liegen unter %LOCALAPPDATA%\\KLIKER Blocks\\LanguageModels\\Packages. Ein eigenes Python ist nur bei Bedarf nötig. Der Verbindungsfehler bei 127.0.0.1:5000 betrifft den optionalen LibreTranslate-Server, nicht die Offline-Übersetzung."
        ]
    };

    private static readonly string[] Codes = ["ru", "en", "fr", "es", "zh", "de"];
    public static IEnumerable<string> Keys => Lines.Keys;
    public static bool IsComplete => Lines.Values.Concat(Captions.Values).Concat(HelpSections.Values)
        .Concat(LanguageNames.Values)
        .All(values => values.Length == Codes.Length && values.All(v => !string.IsNullOrWhiteSpace(v)));
    public static string Get(string key) => key == "help_overview" ? (UiLanguage.Code switch
    {
        "en" => "Kliker Blocks {{VERSION}} is a public beta visual Windows scenario editor. On first launch, choose English or Russian before the editor and demo open; change it later in Languages. Each block has a copyable example graph in Help. The demo uses its own Notepad document and follows the interface language. The release includes separate x64 and x86 portable builds and single-file installers. Scenario → Start with Windows toggles autostart for your Windows account. Pin the running app through the Windows taskbar context menu.",
        "fr" => "Kliker Blocks {{VERSION}} est une version bêta publique de l'éditeur visuel de scénarios Windows. Chaque bloc possède un exemple de graphe copiable dans l'aide.",
        "es" => "Kliker Blocks {{VERSION}} es una versión beta pública del editor visual de escenarios de Windows. Cada bloque tiene un ejemplo de grafo copiable en la ayuda.",
        "zh" => "Kliker Blocks {{VERSION}} 是 Windows 可视化场景编辑器的公开测试版。帮助中每个模块都有可复制的示例图。",
        "de" => "Kliker Blocks {{VERSION}} ist eine öffentliche Beta des visuellen Windows-Szenarioeditors. Für jeden Block gibt es ein kopierbares Beispiel in der Hilfe.",
        _ => "Kliker Blocks {{VERSION}} — публичная бета визуального редактора сценариев Windows. При первом запуске выберите русский или английский до открытия редактора и демонстрации. В справке каждого блока есть копируемый граф примера. Выпуск содержит отдельные переносимые сборки и однофайловые установщики для x64 и x86; автозапуск настраивается в меню «Сценарий»."
    }).Replace("{{VERSION}}", AppIdentity.VersionLabel)
        : Lines[key][Math.Max(0, Array.IndexOf(Codes, UiLanguage.Code))];
    public static string Format(string key, params object[] args) => string.Format(CultureInfo.InvariantCulture, Get(key), args);
    public static string ShapeOptions => string.Join('\n', Get("shape_star"), Get("shape_heart"), Get("shape_house"));
    public static string RetryOptions => ShapeOptions + "\n" + Get("none");
    public static string ColorOptions => string.Join('\n', Get("color_red"), Get("color_blue"), Get("color_yellow"), Get("color_green"));
    public static string Caption(string action, string original) => Captions.TryGetValue(action, out var values)
        ? values[Math.Max(0, Array.IndexOf(Codes, UiLanguage.Code))] : UiLanguage.T(original);
    public static string? HelpSection(string title) => title == "Обзор Kliker Blocks" ? Get("help_overview") :
        title == "Демонстрация Что я умею" ? UiLanguage.Code == "en"
            ? "What I can do runs after your consent. It asks for a name and a short phrase, creates its own Notepad document even if the app is already open, and verifies the active tab before typing. It then draws a chosen shape with the mouse in Paint. If you choose another shape, it undoes only its previous strokes and draws again. Four movable color images then open; Kliker Blocks finds the chosen color and centers its window. The last chapter demonstrates variables, arrays, conditions, loops, INI, files, clipboard and the journal. Translation is not part of this demo. Saved files and windows remain; paths are logged. Stop or Esc interrupts later actions."
            : "Граф «Что я умею» запускается после вашего согласия. Он спрашивает имя и короткую фразу, создаёт собственный документ Блокнота даже при уже открытой программе и проверяет активную вкладку перед вводом. Затем граф рисует мышью выбранную фигуру в Paint. При повторном выборе он отменяет только свои прежние штрихи и рисует снова. Далее открываются четыре перемещаемые цветные картинки: Kliker Blocks находит выбранный цвет и ставит окно по центру. Последняя глава показывает переменные, массивы, условия, циклы, INI, файлы, буфер и журнал. Перевод в демонстрацию не входит. Файлы и окна остаются; пути записываются в журнал. Стоп или Esc прерывает дальнейшие действия." :
        title == "Перевод текста и языковые модели" ? UiLanguage.Code == "en"
            ? "The lightweight edition has Russian/English UI and no bundled Python or translation models. Translate text and Translate array use a configured LibreTranslate server by default; a localhost address without a server will fail. The remote service receives the submitted text. For offline translation, click Download offline language pair in a translation block or Download offline translation in Languages. After your approval, Kliker Blocks downloads Python, Argos and only the selected models. Choose Argos local in the block. Non-English pairs may use English as an intermediate language; reverse translation requires a separate model. Detect language still requires LibreTranslate. If translation available can check either the service or installed Argos models."
            : "Облегчённая версия содержит русский/английский интерфейс без встроенных Python и моделей перевода. «Перевести текст» и «Перевести массив» по умолчанию используют настроенный сервис LibreTranslate; адрес localhost без сервера приведёт к ошибке. Удалённый сервис получает переданный текст. Для офлайн-перевода нажмите кнопку загрузки пары в свойствах блока или меню «Языки → Скачать офлайн-перевод…». После согласия Kliker Blocks загрузит Python, Argos и только выбранные модели. Затем выберите «Argos локально». Между неанглийскими языками может использоваться промежуточный английский; обратное направление требует отдельного пакета. «Определить язык» по-прежнему требует LibreTranslate. «Если перевод доступен» умеет проверять сервис или локальные модели." :
        title == "Установка модели Argos" ? UiLanguage.Code == "en"
            ? "1. Open Languages → Interface languages and translation models → Download offline translation, or click Download offline language pair in a translation block.\n2. Select source and target (ru/en/fr/es/zh/de), optionally the reverse direction, then confirm the download. Kliker Blocks downloads a Python 3.13 installer from python.org, installs a private Argos environment from PyPI, and downloads only the selected model packages from the Argos catalogue. Internet access and disk space are required; this may be hundreds of megabytes.\n3. Once ready, select Argos local in the block. No Kliker Blocks restart is needed. The engine and models are stored under %LOCALAPPDATA%\\KLIKER Blocks. A model in the opposite direction does not substitute for the selected direction.\n4. Alternatively, configure a trusted LibreTranslate service URL. Kliker Blocks does not start that server. The default 127.0.0.1:5000 fails when no server listens there."
            : "1. Откройте «Языки → Язык интерфейса и модели перевода… → Скачать офлайн-перевод…» либо кнопку загрузки в блоке перевода.\n2. Выберите исходный и целевой язык (ru/en/fr/es/zh/de), при желании обратное направление и подтвердите загрузку. Kliker Blocks скачает установщик Python 3.13 с python.org, создаст отдельное окружение Argos из PyPI и загрузит только нужные пакеты из каталога Argos. Нужны интернет и место на диске; объём может составить сотни мегабайт.\n3. После установки выберите «Argos локально» в блоке. Перезапуск Kliker Blocks не нужен. Движок и модели сохраняются в %LOCALAPPDATA%\\KLIKER Blocks. Пакет обратного направления не заменяет выбранное.\n4. Альтернатива — адрес доверенного сервиса LibreTranslate. Kliker Blocks не запускает сервер; стандартный 127.0.0.1:5000 без сервера недоступен." :
        ShowcaseHelp68.Section(title) ??
        (HelpSections.TryGetValue(title, out var values)
            ? values[Math.Max(0, Array.IndexOf(Codes, UiLanguage.Code))] : null);
    public static string? HelpBlock(string kind) => kind == "ShowcaseStep"
        ? HelpSection("Демонстрация Что я умею") : null;
    private static readonly Dictionary<string, string[]> LanguageNames = new(StringComparer.Ordinal)
    {
        ["ru"] = ["русского", "Russian", "russe", "ruso", "俄语", "Russisch"],
        ["en"] = ["английского", "English", "anglais", "inglés", "英语", "Englisch"],
        ["fr"] = ["французского", "French", "français", "francés", "法语", "Französisch"],
        ["es"] = ["испанского", "Spanish", "espagnol", "español", "西班牙语", "Spanisch"],
        ["zh"] = ["китайского", "Chinese", "chinois", "chino", "中文", "Chinesisch"],
        ["de"] = ["немецкого", "German", "allemand", "alemán", "德语", "Deutsch"]
    };
    private static readonly Dictionary<string, string> RussianTargetNames = new()
    {
        ["ru"] = "русский", ["en"] = "английский", ["fr"] = "французский",
        ["es"] = "испанский", ["zh"] = "китайский", ["de"] = "немецкий"
    };
    public static string LanguageOptions => string.Join('\n', UiLanguage.Available.Select(pair => TargetLanguageName(pair.Code)));
    public static string LanguageName(string code) => LanguageNames[code][Math.Max(0, Array.IndexOf(Codes, UiLanguage.Code))];
    public static string TargetLanguageName(string code) => UiLanguage.Code == "ru"
        ? RussianTargetNames[code] : LanguageName(code);
}



